1	// Real CompanyProvider backed by the Crustdata HTTP API. Mirrors the
2	// FixtureProvider's semantics: BudgetGuard is checked before every paid call,
3	// spend is recorded after success, enrich results are partial, and a call with
4	// no results is no_match. Providers return errors; they do not throw.
5	//
6	// Error messages are deliberately generic (status code and category only).
7	// They never contain the response body, the URL list or any header.
8	
9	import type { RawCompany, RawLocation } from "../types";
10	import {
11	  type BudgetGuard,
12	  type CompanyProvider,
13	  type ProviderErrorCategory,
14	  type ProviderResult,
15	  type SearchFilters,
16	} from "./provider";
17	
18	// Measured on our account (Oct 10-11, 2026, five measurements). Unmatched
19	// enrichments are assumed free (unverified).
20	export const CRUSTDATA_PRICE_PER_SEARCH_RECORD_USD = 0.069;
21	export const CRUSTDATA_PRICE_PER_ENRICHED_COMPANY_USD = 0.6;
22	
23	const API_VERSION = "2025-11-01";
24	const ENRICH_CHUNK_SIZE = 25;
25	const MAX_RETRY_AFTER_MS = 60_000;
26	
27	const SEARCH_FIELDS = [
28	  "crustdata_company_id",
29	  "basic_info.logo_permalink",
30	  "basic_info.name",
31	  "basic_info.primary_domain",
32	  "basic_info.website",
33	  "basic_info.professional_network_url",
34	  "basic_info.employee_count_range",
35	  "taxonomy.professional_network_industry",
36	];
37	
38	const ENRICH_FIELD_GROUPS = ["basic_info", "headcount", "locations", "taxonomy"];
39	
40	export interface CrustdataProviderOptions {
41	  readonly api_key: string;
42	  readonly budget: BudgetGuard;
43	  // Default https://api.crustdata.com
44	  readonly base_url?: string;
45	  // Default global fetch.
46	  readonly fetch?: typeof fetch;
47	  // Per-attempt timeout. Default 30000.
48	  readonly timeout_ms?: number;
49	  // Retries after the first attempt for 429 / 5xx / network errors. Default 2.
50	  readonly max_retries?: number;
51	  // Wait function used between retries. Default setTimeout. Mainly for tests.
52	  readonly sleep?: (ms: number) => Promise<void>;
53	}
54	
55	type Failure = { readonly ok: false; readonly error: { readonly category: ProviderErrorCategory; readonly message: string } };
56	type Json = unknown;
57	
58	export class CrustdataProvider implements CompanyProvider {
59	  readonly budget: BudgetGuard;
60	  private readonly api_key: string;
61	  private readonly base_url: string;
62	  private readonly fetch_fn: typeof fetch;
63	  private readonly timeout_ms: number;
64	  private readonly max_retries: number;
65	  private readonly sleep: (ms: number) => Promise<void>;
66	
67	  constructor(options: CrustdataProviderOptions) {
68	    this.api_key = options.api_key;
69	    this.budget = options.budget;
70	    this.base_url = (options.base_url ?? "https://api.crustdata.com").replace(/\/+$/, "");
71	    this.fetch_fn = options.fetch ?? ((input, init) => fetch(input, init));
72	    this.timeout_ms = options.timeout_ms ?? 30_000;
73	    this.max_retries = options.max_retries ?? 2;
74	    this.sleep = options.sleep ?? ((ms) => new Promise((resolve) => setTimeout(resolve, ms)));
75	  }
76	
77	  async autocompleteIndustry(query: string): Promise<ProviderResult<readonly string[]>> {
78	    const res = await this.post("/company/search/autocomplete", {
79	      field: "taxonomy.professional_network_industry",
80	      query,
81	      limit: 10,
82	    });
83	    if (!res.ok) return res;
84	    const raw = asRecord(res.json)?.suggestions;
85	    const values = (Array.isArray(raw) ? raw : [])
86	      .map((s) => str(asRecord(s)?.value))
87	      .filter((v) => v !== "");
88	    if (values.length === 0) return fail("no_match", "no industry suggestions");
89	    // Autocomplete is free and outside the search/enrich caps.
90	    return { ok: true, data: values, cost_usd: 0, calls: res.calls };
91	  }
92	
93	  async searchCompanies(
94	    filters: SearchFilters,
95	    limit: number,
96	  ): Promise<ProviderResult<readonly RawCompany[]>> {
97	    if (!this.budget.canSearch(limit)) {
98	      return fail("budget_cap_reached", "search cap would be exceeded");
99	    }
100	    const conditions: Record<string, unknown>[] = [];
101	    if (filters.country !== "") {
102	      conditions.push({ field: "locations.country", type: "=", value: filters.country });
103	    }
104	    if (filters.industries.length > 0) {
105	      conditions.push({
106	        field: "taxonomy.professional_network_industry",
107	        type: "in",
108	        value: filters.industries,
109	      });
110	    }
111	    if (filters.employee_count_ranges.length > 0) {
112	      conditions.push({
113	        field: "basic_info.employee_count_range",
114	        type: "in",
115	        value: filters.employee_count_ranges,
116	      });
117	    }
118	    const body: Record<string, unknown> = {
119	      sorts: [{ field: "basic_info.name", order: "asc" }],
120	      fields: SEARCH_FIELDS,
121	      limit,
122	    };
123	    if (conditions.length > 0) body.filters = { op: "and", conditions };
124	
125	    const res = await this.post("/company/search", body);
126	    if (!res.ok) return res;
127	    const now = new Date().toISOString();
128	    const found = extractList(res.json)
129	      .slice(0, Math.max(limit, 0))
130	      .map((item) => mapSearchItem(item, now));
131	    if (found.length === 0) return fail("no_match", "no companies match the filters");
132	    const total = CRUSTDATA_PRICE_PER_SEARCH_RECORD_USD * found.length;
133	    const data = found.map((c): RawCompany => ({ ...c, cost_usd: CRUSTDATA_PRICE_PER_SEARCH_RECORD_USD }));
134	    this.budget.recordSearch(found.length, total);
135	    return { ok: true, data, cost_usd: total, calls: res.calls };
136	  }
137	
138	  async enrichCompanies(
139	    linkedin_urls: readonly string[],
140	  ): Promise<ProviderResult<readonly RawCompany[]>> {
141	    if (!this.budget.canEnrich(linkedin_urls.length)) {
142	      return fail("budget_cap_reached", "enrichment cap would be exceeded");
143	    }
144	    const matched: RawCompany[] = [];
145	    let cost = 0;
146	    let calls = 0;
147	    let first_failure: Failure | undefined;
148	
149	    for (let i = 0; i < linkedin_urls.length; i += ENRICH_CHUNK_SIZE) {
150	      const chunk = linkedin_urls.slice(i, i + ENRICH_CHUNK_SIZE);
151	      if (!this.budget.canEnrich(chunk.length)) {
152	        first_failure ??= fail("budget_cap_reached", "enrichment cap would be exceeded");
153	        break;
154	      }
155	      const res = await this.post("/company/enrich", {
156	        fields: ENRICH_FIELD_GROUPS,
157	        professional_network_profile_urls: chunk,
158	      });
159	      calls += res.calls;
160	      if (!res.ok) {
161	        first_failure ??= res;
162	        break;
163	      }
164	      const now = new Date().toISOString();
165	      const records = (Array.isArray(res.json) ? res.json : [])
166	        .map((element) => mapEnrichElement(element, now))
167	        .filter((c): c is RawCompany => c !== undefined);
168	      const chunk_cost = CRUSTDATA_PRICE_PER_ENRICHED_COMPANY_USD * records.length;
169	      this.budget.recordEnrich(records.length, chunk_cost);
170	      matched.push(...records);
171	      cost += chunk_cost;
172	    }
173	
174	    // Partial results win over a later chunk's failure, like a partial match.
175	    if (matched.length > 0) return { ok: true, data: matched, cost_usd: cost, calls };
176	    return first_failure ?? fail("no_match", "no companies matched the LinkedIn URLs");
177	  }
178	
179	  // One POST with retries on 429, 5xx and network errors.
180	  private async post(
181	    path: string,
182	    body: unknown,
183	  ): Promise<{ ok: true; json: Json; calls: number } | (Failure & { calls: number })> {
184	    let calls = 0;
185	    for (let attempt = 0; ; attempt++) {
186	      calls += 1;
187	      const outcome = await this.attempt(path, body);
188	      if (outcome.kind === "ok") return { ok: true, json: outcome.json, calls };
189	      const failure = { ...fail(outcome.category, outcome.message), calls };
190	      if (!outcome.retryable || attempt >= this.max_retries) return failure;
191	      await this.sleep(outcome.retry_after_ms ?? 1000 * 2 ** attempt);
192	    }
193	  }
194	
195	  private async attempt(
196	    path: string,
197	    body: unknown,
198	  ): Promise<
199	    | { kind: "ok"; json: Json }
200	    | {
201	        kind: "error";
202	        category: ProviderErrorCategory;
203	        message: string;
204	        retryable: boolean;
205	        retry_after_ms?: number;
206	      }
207	  > {
208	    const controller = new AbortController();
209	    const timer = setTimeout(() => controller.abort(), this.timeout_ms);
210	    try {
211	      const response = await this.fetch_fn(`${this.base_url}${path}`, {
212	        method: "POST",
213	        headers: {
214	          "Content-Type": "application/json",
215	          Authorization: `Bearer ${this.api_key}`,
216	          "x-api-version": API_VERSION,
217	        },
218	        body: JSON.stringify(body),
219	        signal: controller.signal,
220	      });
221	      const status = response.status;
222	      if (status >= 200 && status < 300) {
223	        try {
224	          return { kind: "ok", json: await response.json() };
225	        } catch {
226	          return err("empty_or_partial", `HTTP ${status} unreadable response`, false);
227	        }
228	      }
229	      if (status === 401 || status === 403) return err("auth_failed", `HTTP ${status} auth_failed`, false);
230	      if (status === 429) {
231	        return {
232	          ...err("rate_limited", `HTTP ${status} rate_limited`, true),
233	          retry_after_ms: parseRetryAfter(response.headers?.get("retry-after") ?? null),
234	        };
235	      }
236	      if (status >= 500) return err("timeout", `HTTP ${status} timeout`, true);
237	      return err("bad_request", `HTTP ${status} bad_request`, false);
238	    } catch {
239	      return err("timeout", "request failed or timed out (timeout)", true);
240	    } finally {
241	      clearTimeout(timer);
242	    }
243	  }
244	}
245	
246	function err(category: ProviderErrorCategory, message: string, retryable: boolean) {
247	  return { kind: "error" as const, category, message, retryable };
248	}
249	
250	function fail(category: ProviderErrorCategory, message?: string): Failure {
251	  return { ok: false, error: { category, message: message ?? category } };
252	}
253	
254	function parseRetryAfter(value: string | null): number | undefined {
255	  if (value === null) return undefined;
256	  const seconds = Number(value);
257	  if (!Number.isFinite(seconds) || seconds < 0) return undefined;
258	  return Math.min(seconds * 1000, MAX_RETRY_AFTER_MS);
259	}
260	
261	// --- Mapping helpers: never throw on missing or null fields. ---------------
262	
263	function asRecord(v: unknown): Record<string, unknown> | undefined {
264	  return typeof v === "object" && v !== null && !Array.isArray(v)
265	    ? (v as Record<string, unknown>)
266	    : undefined;
267	}
268	
269	function str(v: unknown): string {
270	  return typeof v === "string" ? v : "";
271	}
272	
273	function num(v: unknown): number | undefined {
274	  return typeof v === "number" && Number.isFinite(v) ? v : undefined;
275	}
276	
277	// Reads "a.b" as nested a -> b.
278	function pick(obj: Record<string, unknown> | undefined, path: string): unknown {
279	  let cur: unknown = obj;
280	  for (const part of path.split(".")) cur = asRecord(cur)?.[part];
281	  return cur;
282	}
283	
284	// The search response is { companies: [...], next_cursor, total_count }.
285	function extractList(json: Json): unknown[] {
286	  const list = asRecord(json)?.companies;
287	  return Array.isArray(list) ? list : [];
288	}
289	
290	function mapSearchItem(item: unknown, retrieved_at: string): RawCompany {
291	  const o = asRecord(item);
292	  return {
293	    crustdata_company_id: num(pick(o, "crustdata_company_id")) ?? 0,
294	    name: str(pick(o, "basic_info.name")),
295	    primary_domain: str(pick(o, "basic_info.primary_domain")),
296	    website: str(pick(o, "basic_info.website")),
297	    professional_network_url: str(pick(o, "basic_info.professional_network_url")),
298	    employee_count_range: str(pick(o, "basic_info.employee_count_range")),
299	    industry: str(pick(o, "taxonomy.professional_network_industry")),
300	    logo: str(pick(o, "basic_info.logo_permalink")),
301	    source: "search",
302	    retrieved_at,
303	    cost_usd: 0,
304	  };
305	}
306	
307	// One element per input URL; takes the highest-confidence match, if any.
308	function mapEnrichElement(element: unknown, retrieved_at: string): RawCompany | undefined {
309	  const matches = asRecord(element)?.matches;
310	  if (!Array.isArray(matches)) return undefined;
311	  let best: Record<string, unknown> | undefined;
312	  let best_score = -Infinity;
313	  for (const m of matches) {
314	    const rec = asRecord(m);
315	    if (!rec || !asRecord(rec.company_data)) continue;
316	    const score = num(rec.confidence_score) ?? 0;
317	    if (score > best_score) {
318	      best = rec;
319	      best_score = score;
320	    }
321	  }
322	  const d = asRecord(best?.company_data);
323	  if (!d) return undefined;
324	
325	  const basic = asRecord(d.basic_info);
326	  const loc = asRecord(d.locations);
327	  const tax = asRecord(d.taxonomy);
328	
329	  // Only city / state / country are ever copied from locations.
330	  const location: { -readonly [K in keyof RawLocation]: RawLocation[K] } = {};
331	  if (str(loc?.city) !== "") location.city = str(loc?.city);
332	  if (str(loc?.state) !== "") location.state = str(loc?.state);
333	  if (str(loc?.country) !== "") location.country = str(loc?.country);
334	
335	  const founded = num(basic?.year_founded);
336	  const headcount = num(asRecord(d.headcount)?.total);
337	  const description = str(basic?.description);
338	  const legal_type = str(basic?.company_type);
339	  const specialities = Array.isArray(tax?.professional_network_specialities)
340	    ? (tax.professional_network_specialities as unknown[]).filter(
341	        (s): s is string => typeof s === "string" && s !== "",
342	      )
343	    : [];
344	
345	  return {
346	    crustdata_company_id: num(d.crustdata_company_id) ?? 0,
347	    name: str(basic?.name),
348	    primary_domain: str(basic?.primary_domain),
349	    website: str(basic?.website),
350	    professional_network_url: str(basic?.professional_network_url),
351	    employee_count_range: str(basic?.employee_count_range),
352	    industry: str(tax?.professional_network_industry),
353	    logo: str(basic?.logo_permalink),
354	    ...(description !== "" && { description }),
355	    ...(legal_type !== "" && { legal_type }),
356	    ...(founded !== undefined && { founded_year: founded }),
357	    ...(headcount !== undefined && { latest_headcount: headcount }),
358	    ...(Object.keys(location).length > 0 && { location }),
359	    ...(specialities.length > 0 && { specialities }),
360	    source: "enrich",
361	    retrieved_at,
362	    cost_usd: CRUSTDATA_PRICE_PER_ENRICHED_COMPANY_USD,
363	  };
364	}
